(()=>{const esc=value=>String(value||'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x])),field=(label,name,value='',placeholder='',type='text')=>`<label><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" placeholder="${placeholder}"></label>`,area=(label,name,value='',placeholder='',rows=3)=>`<label><span>${label}</span><textarea name="${name}" rows="${rows}" placeholder="${placeholder}">${esc(value)}</textarea></label>`;function title(company){const c=company.capabilities||[];return c.includes('contractor')&&c.includes('subcontractor')?'Contractor & Subcontractor Profile':c.includes('contractor')?'Contractor Profile':'Subcontractor Profile'}function image(company){return company.profileImage?`<img class="company-profile-image" src="${esc(company.profileImage)}" alt="${esc(company.name)} profile picture">`:`<span class="company-profile-placeholder">${initials(company.name)}</span>`}function trustTools(result){const projects=result.portfolio.map(x=>`<article class="portfolio-card"><img src="${esc(x.photoUrl)}" alt="${esc(x.title)}"><div><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p></div></article>`).join(''),credentials=result.credentials.map(x=>`<article class="credential-profile-card"><span class="connection-status">${esc(x.verificationStatus)}</span><h3>${esc(x.name)}</h3><p>${esc(x.type)} · ${esc(x.issuer)}</p><small>${esc(x.coverage||x.credentialNumber)}</small></article>`).join('');return`<section class="profile-trust-section"><div class="profile-section-heading"><span class="kicker">Due diligence</span><h3>Completed work, licenses, and insurance</h3></div><div class="profile-manage-grid"><form class="workspace-card profile-form-section" id="rolePortfolioForm"><h3>Add completed work</h3>${field('Project title','title','','Recent completed project')}${field('Trade','trade','','Select a trade')}${field('Photo URL','photoUrl','','https://...','url')}${area('Description','description','','Describe the completed scope.',3)}<button class="button button-orange" type="submit">Add project</button></form><form class="workspace-card profile-form-section" id="roleCredentialForm"><h3>Add license or insurance</h3><label><span>Type</span><select name="type"><option value="license">License</option><option value="insurance">Insurance</option><option value="certification">Certification</option><option value="bond">Bond</option></select></label>${field('Name','name','','General liability insurance')}${field('Issuer','issuer','','Issuer')}${field('Number','credentialNumber','','Credential number')}${field('Coverage','coverage','','$2M aggregate or classification')}<button class="button button-dark" type="submit">Add credential</button></form></div><div class="profile-results"><div><h3>Recent completed work</h3><div class="portfolio-grid">${projects||'<div class="list-empty">No completed-work photos yet.</div>'}</div></div><div><h3>Credentials</h3><div class="credential-profile-grid">${credentials||'<div class="list-empty">No licenses or insurance posted yet.</div>'}</div></div></div></section>`}async function render(){if(!window.dashboard?.company)return;const result=await api(`/api/profiles/${dashboard.company.id}`),company=result.company,roles=company.capabilities||[],isContractor=roles.includes('contractor'),isSub=roles.includes('subcontractor'),pageTitle=title(company),root=document.getElementById('profileDetails'),heading=document.getElementById('profileCompany'),nav=document.querySelector('[data-view="profile"]');heading.textContent=pageTitle;if(nav)nav.textContent=pageTitle;root.innerHTML=`<div class="role-profile-intro"><div>${image(company)}</div><div><span class="kicker">${esc(pageTitle)}</span><h3>${esc(company.name)}</h3><p>Complete this information so trade partners can understand your business before starting a conversation or hiring decision.</p></div></div><form class="role-profile-form" id="roleProfileForm"><section class="workspace-card profile-form-section"><div class="profile-section-heading"><span class="kicker">Business identity</span><h3>Core company information</h3></div><div class="company-picture-row"><label class="button button-outline">Upload profile picture<input id="roleProfileImage" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><button id="removeRoleProfileImage" class="text-link" type="button">Remove picture</button><small>PNG, JPG, or WebP under 1.5 MB.</small></div><div class="form-row">${field('Legal company name','legalName',company.legalName,'Legal business name')}${field('Year founded','yearFounded',company.yearFounded,'2012')}</div><div class="form-row">${field('Public phone','phone',company.phone,'(214) 555-0123')}${field('Public email','contactEmail',company.contactEmail,'estimating@company.com','email')}</div>${field('Website','website',company.website,'https://company.com','url')}${field('Street address','streetAddress',company.streetAddress,'Business address')}${area('About the business','about',company.about,'Describe your team, experience, specialties, and what makes your company dependable.',5)}<div class="form-row">${field('Company size','employeeCount',company.employeeCount,'Example: 11-25')}${field('Service area summary','serviceSummary',company.serviceSummary,'Example: DFW and surrounding 75 miles')}</div></section>${isContractor?`<section class="workspace-card profile-form-section contractor-profile-section"><div class="profile-section-heading"><span class="kicker">Contractor information</span><h3>Help subcontractors understand how you hire</h3></div>${area('Typical project types','projectTypes',company.projectTypes,'Commercial interiors, multifamily renovations, ground-up retail...',3)}<div class="form-row">${field('Annual project volume','annualProjectVolume',company.annualProjectVolume,'Example: $5M-$10M')}${field('Payment terms','paymentTerms',company.paymentTerms,'Example: Net 30')}</div>${area('Subcontractor requirements','subcontractorRequirements',company.subcontractorRequirements,'Insurance limits, safety requirements, onboarding documents, scheduling expectations...',4)}</section>`:''}${isSub?`<section class="workspace-card profile-form-section subcontractor-profile-section"><div class="profile-section-heading"><span class="kicker">Subcontractor information</span><h3>Help contractors qualify your crew</h3></div><div class="form-row">${field('Crew size','crewSize',company.crewSize,'Example: 8 field employees')}${field('Years of experience','yearsExperience',company.yearsExperience,'Example: 12 years')}</div><div class="form-row">${field('Minimum job size','minimumJobSize',company.minimumJobSize,'Example: $5,000')}${field('Current availability','availability',company.availability,'Example: Booking 3 weeks out')}</div></section>`:''}<div class="profile-save-bar"><button class="button button-orange" type="submit">Save ${esc(pageTitle)}</button><button class="button button-outline" id="previewRoleProfile" type="button">Preview public profile</button></div></form>${isSub?trustTools(result):''}`;let profileImage=company.profileImage||'';document.getElementById('roleProfileImage').onchange=event=>{const file=event.target.files[0];if(!file)return;if(file.size>1500000)return showNotice('Choose an image under 1.5 MB.',true);const reader=new FileReader();reader.onload=()=>{profileImage=reader.result;document.querySelector('.role-profile-intro>div').innerHTML=image({...company,profileImage})};reader.readAsDataURL(file)};document.getElementById('removeRoleProfileImage').onclick=()=>{profileImage='';document.querySelector('.role-profile-intro>div').innerHTML=image({...company,profileImage})};document.getElementById('roleProfileForm').onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('[type="submit"]');button.disabled=true;button.textContent='Saving profile...';try{await api('/api/profile/company',{method:'PUT',body:JSON.stringify({...Object.fromEntries(new FormData(event.currentTarget)),profileImage})});showNotice(`${pageTitle} saved.`);await render()}catch(error){showNotice(error.message,true)}finally{button.disabled=false}};document.getElementById('previewRoleProfile').onclick=()=>window.loadTrustProfile?loadTrustProfile(company.id):showNotice('Profile saved and ready for marketplace partners.');for(const[id,path]of[['rolePortfolioForm','/api/profile/portfolio'],['roleCredentialForm','/api/profile/credentials']]){const form=document.getElementById(id);if(form)form.onsubmit=async event=>{event.preventDefault();try{await api(path,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))});showNotice('Profile updated.');await render()}catch(error){showNotice(error.message,true)}}}}async function open(){switchView('profile');try{await render()}catch(error){showNotice(error.message,true)}}const nav=document.querySelector('[data-view="profile"]');if(nav)nav.addEventListener('click',event=>{event.stopImmediatePropagation();open()},true);if(location.pathname==='/profile')setTimeout(open,250);window.TradesRoleProfile={render,open}})();
